package com.crypto.laplace.stop; import com.crypto.laplace.execution.LaplaceTradeReconciliationService; import lombok.RequiredArgsConstructor; import org.springframework.boot.ApplicationArguments; import org.springframework.boot.ApplicationRunner; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.core.annotation.Order; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor @Order(60) @ConditionalOnProperty(prefix="trading.laplace",name="enabled",havingValue="true") public class LaplaceFiveMinuteStopScheduler implements ApplicationRunner { private final LaplaceFiveMinuteStopService service; private final LaplaceTradeReconciliationService reconciliation; @Override public void run(ApplicationArguments args){if(!reconciliation.isComplete())throw new IllegalStateException("RECONCILIATION_NOT_COMPLETE");service.catchUpOpenPositions();} @Scheduled(cron="${trading.laplace.stop-cron}",zone="${trading.laplace.stop-zone}") public void run(){if(reconciliation.isComplete())service.checkOpenPositions();} }
